import{_ as t,o as e,c as r,ag as d}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"auto_link 质量修法规格（跨主题假边 / 真边漏检）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-brain/auto-link-quality-fixes.md","filePath":"topics/ai-brain/auto-link-quality-fixes.md"}'),n={name:"topics/ai-brain/auto-link-quality-fixes.md"};function s(a,o,i,c,l,g){return e(),r("div",null,[...o[0]||(o[0]=[d('<h1 id="auto-link-质量修法规格-跨主题假边-真边漏检" tabindex="-1">auto_link 质量修法规格（跨主题假边 / 真边漏检） <a class="header-anchor" href="#auto-link-质量修法规格-跨主题假边-真边漏检" aria-label="Permalink to &quot;auto_link 质量修法规格（跨主题假边 / 真边漏检）&quot;">​</a></h1><blockquote><p><strong>状态：规划落盘（未改脚本，零风险）</strong> ｜ 首建 2026-10-20 <strong>背景</strong>：本文件被晨报<strong>连续点名 6 次</strong>（10-08 / 10-10 / 10-11 / 10-12 / 10-13 / 10-20）称&quot;规划未建&quot;。本次只写设计，不修 <code>scripts/auto_link.py</code>——改脚本属高危操作，留待人工确认。 关键词：auto_link、假边、仅文件名互引、关联行、一等边、Echo Gap、知识网络质量、跨主题关联</p></blockquote><hr><h2 id="一、问题-2026-10-20-实测" tabindex="-1">一、问题（2026-10-20 实测） <a class="header-anchor" href="#一、问题-2026-10-20-实测" aria-label="Permalink to &quot;一、问题（2026-10-20 实测）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>观测</th><th>数字</th></tr></thead><tbody><tr><td>跨主题关联总数</td><td>384 条</td></tr><tr><td>其中「（仅文件名互引）」假边</td><td>约 139 条（<strong>≈37%</strong>）</td></tr><tr><td>本期新增跨主题边</td><td>12 条，<strong>全部</strong>来自 <code>topics/ai-tools/android-tv-debloat-cleanyourtv.md</code></td></tr><tr><td>新增边最高强度</td><td><strong>3</strong>（共同词：<code>一句话 / ai / google / 性质</code> —— 通用词）</td></tr><tr><td>该文件 <code>关联：</code> 行明写的真边</td><td>2 条，<strong>进 links.md 的：0 条</strong></td></tr></tbody></table><p><strong>两类系统性失效：</strong></p><ol><li><strong>假边（噪声）</strong>：通用词（<code>一句话</code>、<code>ai</code>、<code>问题</code>、<code>意义</code>）与<strong>同名文件</strong>（如 <code>science-daily-2026-10-13.md</code> 同时落在 7 个主题 → 文件名本身变伪关键词）凭空造边。</li><li><strong>真边漏检</strong>：文件内 <code>关联：</code> / <code>&gt; 关联</code> 行是<strong>作者显式写下的高置信边</strong>，却从未被解析为一等边。本期 2 条真边（AI 工具评测↔网络安全、AI 工具评测↔AI 系统架构）直接丢失。</li></ol><p><strong>为什么这属于 Echo Gap</strong>：pipeline 用<strong>自己的关键词强度分</strong>给自己打分，误差与被评内容相关 → <strong>最自信的假边被反复保留，真边被静默丢弃</strong>。与 <code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code> 同源：自评分通道的误差必须与被评内容<strong>解耦</strong>。</p><hr><h2 id="二、修法-两条-独立可做" tabindex="-1">二、修法（两条，独立可做） <a class="header-anchor" href="#二、修法-两条-独立可做" aria-label="Permalink to &quot;二、修法（两条，独立可做）&quot;">​</a></h2><h3 id="a-把-关联-关联-行解析为一等显式高置信边-【优先级最高-收益立即可见】" tabindex="-1">(a) 把 <code>关联：</code> / <code>&gt; 关联</code> 行解析为一等显式高置信边 【优先级最高，收益立即可见】 <a class="header-anchor" href="#a-把-关联-关联-行解析为一等显式高置信边-【优先级最高-收益立即可见】" aria-label="Permalink to &quot;(a) 把 `关联：` / `&gt; 关联` 行解析为一等显式高置信边 【优先级最高，收益立即可见】&quot;">​</a></h3><ul><li>匹配形如：<code>关联：\\</code>path/a.md`（说明）、`topics/b/`（说明）`</li><li>解析规则：反引号内若是<strong>文件路径</strong> → 直接建边 <code>该文件 ↔ 目标文件</code>（置信度 = explicit）；若是<strong>目录</strong> → 建边到该主题 index，标记 <code>topic-level</code>。</li><li>落盘时<strong>单列一节</strong>：<code>## 🔗 显式关联（作者标注）</code>，与关键词边分列，不参与强度排序混算。</li><li>预期收益：本期即可救回 2 条真边；历史上 36 期起所有带 <code>关联：</code> 行的文件同步受益。</li></ul><h3 id="b-「仅文件名互引」与通用词边单独降权、分列计价" tabindex="-1">(b) 「仅文件名互引」与通用词边单独降权、分列计价 <a class="header-anchor" href="#b-「仅文件名互引」与通用词边单独降权、分列计价" aria-label="Permalink to &quot;(b) 「仅文件名互引」与通用词边单独降权、分列计价&quot;">​</a></h3><ul><li>「（仅文件名互引）」<strong>不计入跨主题强度分</strong>，单列 <code>## 📎 弱关联（仅文件名/目录互引）</code>。</li><li>引入<strong>通用词黑名单</strong>（在现有 stopwords 上补）：<code>一句话、性质、问题、意义、分类、状态、母题、注意、连接、约束、合计、目的、作者、代表</code> 等。</li><li><strong>同名文件降权</strong>：同一文件出现在 ≥3 个主题时，其文件名不得作为关键词参与建边（解决 science-daily 系列的伪关键词问题）。</li><li>强度分只由<strong>非通用、非文件名关键词</strong>贡献。</li></ul><hr><h2 id="三、验证方法-改后必须跑" tabindex="-1">三、验证方法（改后必须跑） <a class="header-anchor" href="#三、验证方法-改后必须跑" aria-label="Permalink to &quot;三、验证方法（改后必须跑）&quot;">​</a></h2><ol><li><code>python3 scripts/auto_link.py</code> → 记录跨主题边总数、假边占比。</li><li>人工抽检：本期 2 条真边（AI 工具评测 ↔ 网络安全 / AI 系统架构）<strong>必须</strong>出现在「显式关联」节。</li><li>回归：确认 <code>links/links.md</code> 的三节结构仍可被 <code>query_brain.py</code> / <code>knowledge_graph.py</code> 正常读取。</li></ol><hr><h2 id="四、风险" tabindex="-1">四、风险 <a class="header-anchor" href="#四、风险" aria-label="Permalink to &quot;四、风险&quot;">​</a></h2><ul><li>修改 <code>scripts/auto_link.py</code> 会影响每日晨报与每周维护任务 → <strong>须人工确认后执行</strong>，并在改前 <code>git commit</code> 备份当前版本。</li><li>解析 <code>关联：</code> 行时注意路径可能是相对路径（相对仓库根）或纯文件名，需要容错（找不到文件 → 记为 <code>unresolved</code>，不静默丢弃）。</li></ul><hr><h2 id="五、新发现-idf-下限会剪掉「新主题的全部独特词」-2026-10-21-实测" tabindex="-1">五、新发现：IDF 下限会剪掉「新主题的全部独特词」（2026-10-21 实测） <a class="header-anchor" href="#五、新发现-idf-下限会剪掉「新主题的全部独特词」-2026-10-21-实测" aria-label="Permalink to &quot;五、新发现：IDF 下限会剪掉「新主题的全部独特词」（2026-10-21 实测）&quot;">​</a></h2><p><strong>触发场景</strong>：新建主题 <code>topics/self-hosting/</code>（2 个文件）后跑 <code>auto_link.py --daily</code>。</p><p><strong>数据</strong>（只读诊断 <code>/tmp/diag.py</code>，未改脚本）：</p><table tabindex="0"><thead><tr><th>观测</th><th>数值</th></tr></thead><tbody><tr><td>主题总数</td><td>37 → <strong>IDF 上限 <code>max_topics = max(2, int(37 × 0.35)) = 12</code></strong></td></tr><tr><td><code>self-hosting</code> 抽出关键词</td><td><strong>109 个</strong></td></tr><tr><td>经 <code>build_keyword_index</code>（保留 <code>2 ≤ n ≤ 12</code>）后<strong>存活</strong></td><td><strong>仅 10 个</strong></td></tr><tr><td>被剪掉的典型词</td><td><strong>树莓派、raspberry pi、adguard home、tailscale、homelab、poe、usb 启动、双频 802.11ac</strong></td></tr></tbody></table><p><strong>机制</strong>：<code>build_keyword_index</code> 只保留&quot;出现在 <strong>≥2 个主题</strong>&quot;的词。而<strong>新主题的独特术语必然只出现在它自己的 1~2 个文件里</strong> → 全被剪掉。存活的反而是 <code>核实 / 支持 / 物理约束 / llm / 去广告</code> 这类<strong>泛词</strong>。</p><p><strong>后果（反直觉）</strong>：建新主题时，<strong>知识网络里最有辨识度的词反而进不了网</strong>；成边全靠泛词 + 文件名互引（后者又是 §一 记录的假边来源）。与 §一 同源：<strong>IDF 按&quot;跨主题普遍性&quot;取词，天然奖励泛词、惩罚专有名词。</strong></p><p><strong>⚠️ 实测口径修正（本轮踩坑，重要）</strong>：复核 <code>links.md</code> <strong>不能 grep 文件名或主题目录名</strong> —— 它只写&quot;主题<strong>中文标题</strong> + 共有词&quot;。本轮若只看 <code>grep -i self-hosting</code> 会误判&quot;未入网&quot;，<strong>实际已入网 10 条边</strong>（含最关键的一条：自托管 ↔ AI外脑 — 知识网络搭建记录，共同词 <code>llm 调用与飞书投递同时失效</code>，恰好就是&quot;看门狗补故障盲区&quot;那个连接）。 → 复核请用：<strong>主题中文标题</strong>（如「自托管与 Homelab」）或<strong>共有词</strong>，别用目录名/文件名。</p><p><strong>修法草案（并入 (b) 一起做）</strong>：</p><ul><li><strong>新主题豁免</strong>：对文件数 ≤2 的主题跳过 <code>n ≥ 2</code> 下限，其独特词以<strong>低权重</strong>入网（strength × 0.5），单列 <code>## 🆕 新主题首连</code>。</li><li>或 <strong>保底机制</strong>：每个主题至少贡献 top-K（如 5）个独特词参与建边，保证新主题不会&quot;零独特词入网&quot;。</li><li><strong>验证</strong>：<code>self-hosting</code> 应至少出现 <code>树莓派 / raspberry pi / adguard</code> 三条边，且无 <code>（仅文件名互引）</code> 假边。</li></ul><hr><p>关联：<code>topics/ai-brain/index.md</code>、<code>scripts/auto_link.py</code>、<code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code>、<code>topics/self-hosting/index.md</code>、<code>memory/work/daily/2026-10-20.md</code></p>',32)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
